// FILE: p2p-kids-admin/src/components/spconfig/DateRangePicker.tsx
// ADMIN-V3-006: Reusable date range picker component

'use client';

import React from 'react';

interface DateRangePickerProps {
  /** Current selected days (7, 30, or 90) */
  value: number;
  /** Callback when selection changes */
  onChange: (days: number) => void;
  /** Optional test ID prefix */
  testIdPrefix?: string;
}

/**
 * Date range picker with 7 / 30 / 90 day buttons
 * Defaults to 30 days
 */
export function DateRangePicker({
  value,
  onChange,
  testIdPrefix = 'date-range',
}: DateRangePickerProps) {
  const ranges = [
    { days: 7, label: 'Last 7 Days' },
    { days: 30, label: 'Last 30 Days' },
    { days: 90, label: 'Last 90 Days' },
  ];

  return (
    <div className="flex gap-2" data-testid={`${testIdPrefix}-picker`}>
      {ranges.map(({ days, label }) => (
        <button
          key={days}
          onClick={() => onChange(days)}
          className={`px-4 py-2 rounded-lg transition ${
            value === days
              ? 'bg-blue-600 text-white'
              : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
          }`}
          data-testid={`${testIdPrefix}-${days}`}
          aria-label={label}
          aria-pressed={value === days}
        >
          {label}
        </button>
      ))}
    </div>
  );
}

// FILE: p2p-kids-admin/src/components/spconfig/SPAnomalyAlerts.tsx
// ADMIN-V3-006: Anomaly alerts panel for flagged categories

'use client';

import React from 'react';
import { AlertTriangle, TrendingDown, TrendingUp, Package } from 'lucide-react';
import type { CategorySPAnalytics, AnomalyFlag } from '@/types/category';

interface SPAnomalyAlertsProps {
  /** Analytics data with anomaly flags */
  analytics: CategorySPAnalytics[];
  /** Callback when category is clicked */
  onCategoryClick: (categoryId: string) => void;
}

const ANOMALY_CONFIG: Record<
  AnomalyFlag,
  {
    icon: React.ReactNode;
    label: string;
    description: string;
    color: string;
    bgColor: string;
  }
> = {
  hoarding: {
    icon: <Package size={16} />,
    label: 'Hoarding',
    description: 'Gap > 10% — users earning but not spending',
    color: 'text-yellow-700',
    bgColor: 'bg-yellow-50 border-yellow-200',
  },
  low_velocity: {
    icon: <TrendingDown size={16} />,
    label: 'Low Velocity',
    description: 'Velocity < 0.5 — spending is much lower than earning',
    color: 'text-orange-700',
    bgColor: 'bg-orange-50 border-orange-200',
  },
  spending_spike: {
    icon: <TrendingUp size={16} />,
    label: 'Spending Spike',
    description: 'Velocity > 2 — users spending more SP than earning',
    color: 'text-red-700',
    bgColor: 'bg-red-50 border-red-200',
  },
};

/**
 * Panel showing categories with detected anomalies
 */
export function SPAnomalyAlerts({ analytics, onCategoryClick }: SPAnomalyAlertsProps) {
  const flaggedCategories = analytics.filter((cat) => cat.anomaly_flags.length > 0);

  if (flaggedCategories.length === 0) {
    return (
      <div
        className="bg-green-50 border border-green-200 rounded-lg p-6 text-center"
        data-testid="sp-anomaly-none"
      >
        <div className="text-green-700 font-medium mb-1">✓ All Categories Healthy</div>
        <div className="text-green-600 text-sm">
          No anomalies detected in the selected date range
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-3" data-testid="sp-anomaly-alerts">
      <div className="flex items-center gap-2 text-gray-700 font-medium mb-4">
        <AlertTriangle size={18} className="text-yellow-600" />
        <span>
          {flaggedCategories.length} {flaggedCategories.length === 1 ? 'Category' : 'Categories'}{' '}
          Flagged
        </span>
      </div>

      {flaggedCategories.map((category) => (
        <div
          key={category.category_id}
          className="border rounded-lg p-4 hover:shadow-md transition cursor-pointer"
          onClick={() => onCategoryClick(category.category_id)}
          data-testid={`anomaly-card-${category.category_id}`}
        >
          <div className="font-medium text-gray-900 mb-2">{category.category_name}</div>

          <div className="space-y-2">
            {category.anomaly_flags.map((flag) => {
              const config = ANOMALY_CONFIG[flag];
              return (
                <div
                  key={flag}
                  className={`flex items-center gap-2 text-sm px-3 py-2 border rounded ${config.bgColor} ${config.color}`}
                  data-testid={`anomaly-flag-${flag}`}
                >
                  {config.icon}
                  <div>
                    <span className="font-medium">{config.label}:</span>{' '}
                    <span className="opacity-90">{config.description}</span>
                  </div>
                </div>
              );
            })}
          </div>

          <div className="mt-3 grid grid-cols-3 gap-2 text-xs text-gray-600">
            <div>
              <span className="font-medium">Velocity:</span>{' '}
              {category.velocity.toFixed(2)}
            </div>
            <div>
              <span className="font-medium">Gap:</span> {category.gap_percent.toFixed(1)}%
            </div>
            <div>
              <span className="font-medium">Avg Cash:</span> $
              {category.avg_cash_per_trade.toFixed(2)}
            </div>
          </div>
        </div>
      ))}
    </div>
  );
}

// FILE: p2p-kids-admin/src/components/spconfig/SPMetricsTable.tsx
// ADMIN-V3-006: Per-category metrics table

'use client';

import React from 'react';
import type { CategorySPAnalytics } from '@/types/category';

interface SPMetricsTableProps {
  /** Analytics data per category */
  analytics: CategorySPAnalytics[];
  /** Callback when row is clicked */
  onRowClick: (categoryId: string) => void;
  /** Loading state */
  loading?: boolean;
}

/**
 * Table showing velocity, gap %, and avg cash per trade per category
 */
export function SPMetricsTable({ analytics, onRowClick, loading }: SPMetricsTableProps) {
  if (loading) {
    return (
      <div className="bg-white rounded-lg shadow overflow-hidden">
        <div className="p-8 text-center text-gray-500" data-testid="sp-metrics-loading">
          Loading metrics...
        </div>
      </div>
    );
  }

  if (analytics.length === 0) {
    return (
      <div className="bg-white rounded-lg shadow overflow-hidden">
        <div className="p-8 text-center text-gray-500" data-testid="sp-metrics-empty">
          No category data available for the selected date range
        </div>
      </div>
    );
  }

  return (
    <div className="bg-white rounded-lg shadow overflow-hidden" data-testid="sp-metrics-table">
      <table className="w-full">
        <thead className="bg-gray-50 border-b border-gray-200">
          <tr>
            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
              Category
            </th>
            <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
              Velocity
            </th>
            <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
              Gap %
            </th>
            <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
              Avg Cash / Trade
            </th>
            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
              Anomalies
            </th>
          </tr>
        </thead>
        <tbody className="bg-white divide-y divide-gray-200">
          {analytics.map((category) => {
            const hasAnomalies = category.anomaly_flags.length > 0;

            return (
              <tr
                key={category.category_id}
                onClick={() => onRowClick(category.category_id)}
                className="hover:bg-gray-50 cursor-pointer transition"
                data-testid={`sp-metrics-row-${category.category_id}`}
              >
                <td className="px-6 py-4 whitespace-nowrap">
                  <div className="text-sm font-medium text-gray-900">
                    {category.category_name}
                  </div>
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-right">
                  <div
                    className={`text-sm ${
                      category.velocity < 0.5
                        ? 'text-orange-600 font-medium'
                        : category.velocity > 2
                        ? 'text-red-600 font-medium'
                        : 'text-gray-900'
                    }`}
                    data-testid={`velocity-${category.category_id}`}
                  >
                    {category.velocity.toFixed(2)}
                  </div>
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-right">
                  <div
                    className={`text-sm ${
                      category.gap_percent > 10
                        ? 'text-yellow-600 font-medium'
                        : 'text-gray-900'
                    }`}
                    data-testid={`gap-${category.category_id}`}
                  >
                    {category.gap_percent.toFixed(1)}%
                  </div>
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-right">
                  <div className="text-sm text-gray-900" data-testid={`avg-cash-${category.category_id}`}>
                    ${category.avg_cash_per_trade.toFixed(2)}
                  </div>
                </td>
                <td className="px-6 py-4 whitespace-nowrap">
                  {hasAnomalies ? (
                    <div className="flex flex-wrap gap-1">
                      {category.anomaly_flags.map((flag) => (
                        <span
                          key={flag}
                          className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-medium ${
                            flag === 'hoarding'
                              ? 'bg-yellow-100 text-yellow-800'
                              : flag === 'low_velocity'
                              ? 'bg-orange-100 text-orange-800'
                              : 'bg-red-100 text-red-800'
                          }`}
                          data-testid={`badge-${flag}-${category.category_id}`}
                        >
                          {flag.replace('_', ' ')}
                        </span>
                      ))}
                    </div>
                  ) : (
                    <span className="text-xs text-gray-400">—</span>
                  )}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

// FILE: p2p-kids-admin/src/components/spconfig/SPAnalyticsDashboard.tsx
// ADMIN-V3-006: Main dashboard container with table + alerts

'use client';

import React from 'react';
import { Download } from 'lucide-react';
import type { CategorySPAnalytics } from '@/types/category';
import { SPMetricsTable } from './SPMetricsTable';
import { SPAnomalyAlerts } from './SPAnomalyAlerts';

interface SPAnalyticsDashboardProps {
  /** Analytics data */
  analytics: CategorySPAnalytics[];
  /** Callback when category is clicked */
  onCategoryClick: (categoryId: string) => void;
  /** Callback for CSV export */
  onExportCSV: () => void;
  /** Loading state */
  loading?: boolean;
  /** Current date range in days */
  dateRange: number;
}

/**
 * Main dashboard component with metrics table and anomaly alerts panel
 */
export function SPAnalyticsDashboard({
  analytics,
  onCategoryClick,
  onExportCSV,
  loading,
  dateRange,
}: SPAnalyticsDashboardProps) {
  const flaggedCount = analytics.filter((cat) => cat.anomaly_flags.length > 0).length;

  return (
    <div className="space-y-6" data-testid="sp-analytics-dashboard">
      {/* Header with Export */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-xl font-semibold text-gray-900">Category SP Metrics</h2>
          <p className="text-sm text-gray-600 mt-1">
            Last {dateRange} days · {analytics.length} categories
            {flaggedCount > 0 && ` · ${flaggedCount} flagged`}
          </p>
        </div>
        <button
          onClick={onExportCSV}
          className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition"
          data-testid="export-csv-button"
          aria-label="Export CSV"
        >
          <Download size={16} />
          Export CSV
        </button>
      </div>

      {/* Anomaly Alerts Panel */}
      {!loading && analytics.length > 0 && (
        <div className="bg-white rounded-lg shadow p-6">
          <SPAnomalyAlerts analytics={analytics} onCategoryClick={onCategoryClick} />
        </div>
      )}

      {/* Metrics Table */}
      <SPMetricsTable
        analytics={analytics}
        onRowClick={onCategoryClick}
        loading={loading}
      />
    </div>
  );
}

// FILE: p2p-kids-admin/src/app/sp-analytics/page.tsx
// ADMIN-V3-006: SP Analytics Dashboard Page
// Route: /admin/sp-analytics

'use client';

import React, { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { DateRangePicker } from '@/components/spconfig/DateRangePicker';
import { SPAnalyticsDashboard } from '@/components/spconfig/SPAnalyticsDashboard';
import { getSPAnalyticsByCategory } from '@/lib/spConfigCategoryService';
import type { CategorySPAnalytics } from '@/types/category';

/**
 * SP Analytics Dashboard page
 * Shows per-category velocity, gap %, avg cash flow, and anomaly flags
 */
export default function SPAnalyticsDashboardPage() {
  const router = useRouter();
  const [dateRange, setDateRange] = useState<number>(30); // Default 30 days
  const [analytics, setAnalytics] = useState<CategorySPAnalytics[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Fetch analytics when date range changes
  useEffect(() => {
    async function fetchAnalytics() {
      setLoading(true);
      setError(null);

      try {
        const endDate = new Date();
        const startDate = new Date();
        startDate.setDate(startDate.getDate() - dateRange);

        const data = await getSPAnalyticsByCategory({
          start: startDate.toISOString(),
          end: endDate.toISOString(),
        });

        setAnalytics(data);
      } catch (err) {
        console.error('[SPAnalyticsDashboardPage] Error fetching analytics:', err);
        setError(
          err instanceof Error ? err.message : 'Failed to load analytics. Please try again.'
        );
      } finally {
        setLoading(false);
      }
    }

    fetchAnalytics();
  }, [dateRange]);

  /**
   * Handle category click - navigate to categories page with edit modal + SP Config tab
   */
  const handleCategoryClick = (categoryId: string) => {
    router.push(`/categories?edit=${categoryId}&tab=sp-config`);
  };

  /**
   * Export current analytics snapshot as CSV
   */
  const handleExportCSV = () => {
    if (analytics.length === 0) {
      alert('No data to export');
      return;
    }

    // CSV headers
    const headers = [
      'Category ID',
      'Category Name',
      'Velocity',
      'Gap %',
      'Avg Cash Per Trade',
      'Anomaly Flags',
    ];

    // CSV rows
    const rows = analytics.map((cat) => [
      cat.category_id,
      cat.category_name,
      cat.velocity.toFixed(2),
      cat.gap_percent.toFixed(1),
      cat.avg_cash_per_trade.toFixed(2),
      cat.anomaly_flags.join('; '),
    ]);

    // Generate CSV content
    const csvContent = [
      headers.join(','),
      ...rows.map((row) =>
        row.map((cell) => (typeof cell === 'string' && cell.includes(',') ? `"${cell}"` : cell)).join(',')
      ),
    ].join('\n');

    // Trigger download
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `sp-analytics-${dateRange}days-${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="p-8 max-w-7xl mx-auto" data-testid="sp-analytics-page">
      {/* Header */}
      <div className="mb-8">
        <h1 className="text-3xl font-bold mb-2">SP Analytics Dashboard</h1>
        <p className="text-gray-600">
          Track Swap Points velocity, gap percentage, and cash flow metrics per category
        </p>
      </div>

      {/* Date Range Filter */}
      <div className="mb-6">
        <DateRangePicker value={dateRange} onChange={setDateRange} testIdPrefix="sp-analytics-date-range" />
      </div>

      {/* Error State */}
      {error && (
        <div className="bg-red-50 border border-red-200 rounded-lg p-4 mb-6" data-testid="sp-analytics-error">
          <div className="text-red-800 font-medium">Error Loading Analytics</div>
          <div className="text-red-600 text-sm mt-1">{error}</div>
        </div>
      )}

      {/* Dashboard */}
      <SPAnalyticsDashboard
        analytics={analytics}
        onCategoryClick={handleCategoryClick}
        onExportCSV={handleExportCSV}
        loading={loading}
        dateRange={dateRange}
      />
    </div>
  );
}

